import { randomInt } from "node:crypto";
import { and, eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { cuentas, sesiones } from "@/db/schema";
import { getAuth } from "./server";

/**
 * Passwords are generated by the site, never chosen: a superadmin creates or regenerates
 * one in /admin/clientes, sees it once and passes it on. Only its hash is stored, in the
 * user's "credential" row of `cuentas`, the row Better Auth reads at sign-in.
 */

// No 0/O, 1/l/I: easy to read aloud and to type from a message.
const ALFABETO = "abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789";

/** e.g. "k7Qm-xR4p-W9ta": 12 random characters (about 70 bits), in groups of four. */
export function generarPassword(): string {
  const chars = Array.from({ length: 12 }, () => ALFABETO[randomInt(ALFABETO.length)]);
  return [0, 4, 8].map((i) => chars.slice(i, i + 4).join("")).join("-");
}

/**
 * Gives the user a new password and returns it in clear, to show once. Every open session
 * of that user is closed, so an old password or a lost device stops working at once.
 */
export async function asignarPasswordNueva(usuarioId: number): Promise<string> {
  const password = generarPassword();
  const ctx = await getAuth().$context;
  const hash = await ctx.password.hash(password);

  const [cuenta] = await db
    .select({ id: cuentas.id })
    .from(cuentas)
    .where(and(eq(cuentas.usuarioId, usuarioId), eq(cuentas.providerId, "credential")))
    .limit(1);

  if (cuenta) {
    await db
      .update(cuentas)
      .set({ password: hash, updatedAt: new Date() })
      .where(eq(cuentas.id, cuenta.id));
  } else {
    await db.insert(cuentas).values({
      // Better Auth matches the credential row by accountId = the user's id.
      accountId: String(usuarioId),
      providerId: "credential",
      usuarioId,
      password: hash,
    });
  }

  await db.delete(sesiones).where(eq(sesiones.usuarioId, usuarioId));
  return password;
}
